      G.dun = { rooms: [R], start: R, cur: null, eliteDone: 2, keys: 0, sock: [true, true], bossOpen: true, gate: null, stage: G.stage, altar: true, bx0: 0, bx1: 0, by0: 0, by1: 0 };
      G.loot = []; G.drops = []; G.mood = null;
      enterRoom(R, null);
      const P = G.player; P.x = CX; P.y = A.y1 - 26;
      // v3.20 성문 양옆 벽 기둥 · 창 · 횃불은 enterRoom(05_dungeon.js)에서 좌우 대칭으로 놓음
