      const t = st(), lay = L(), lit = [0, 1, 2].map(i => t >= TL.snap[i] + TL.snapDur);
      list.push({ y: A.y0 - 300, d: () => drawBrand(t, lit) }); // 바닥 낙인 (바닥 바로 위)
      list.push({ y: lay.gb, d: () => drawGate(t) });
