      const q = s.seq, t0 = q.t, t = q.t += dt, hit = (k, at) => { if (!q.ev[k] && t >= at) { q.ev[k] = true; return true; } return false; };
      for (const k in pressed) pressed[k] = false; G.prompt = null; flashT = Math.max(0, flashT - dt);
