        if (u < 1) { ctx.fillStyle = '#d8d2c6'; for (let x = OX - 40; x < OX + 40; x += 2) if (hash(x + Math.floor(time * 12)) < 0.3) ctx.fillRect(x0 + x, y0 + cut, 2, 2); }
