      const R = G.dun && G.dun.cur;
      if (R && R.remains) list.push({ x: CX, y: CY, r: 60, a: 0.3 });
      const s = here(); if (!s) return; const t = time - s.t0, q = s.seq;
      if (q && q.t >= SQ.meadow) return;
