      for (let i = 0; i < 26; i++) { const x = Math.floor(hash(i * 9.1) * GW), y = Math.floor(hash(i * 2.3) * GH); if (x > RX0 - 12 && x < RX1 + 12 && y > top - 8 && y < RY1 + 10) continue; blot(P, x, y, 12, 9, '#0a0d0a', i + 300, 1.2); blot(P, x - 2, y - 2, 6, 4, '#1a241a', i + 330, 0.8); }
