    const cv = sprCv('pan_' + nm, spr.rows, spr.pal, 4); const img = new Image(); img.src = cv.toDataURL(); img.className = 'arcPedImg'; ped.appendChild(img);
    ped.insertAdjacentHTML('beforeend', `<span class="pl">${nm}</span>`);
    sd.appendChild(ped);
