    (fx.jig || []).forEach(([x, y, s]) => { const o = Math.floor(t * 2.5) % 2 ? s : 0; P(x + o, y - 1, FXC[1]); P(x - s + o, y, FXC[1]); P(x + o, y + 1, FXC[1]); }); // 탱글탱글 흔들림
