    for (let i = -8; i <= 8; i++) { const h = 3 + Math.round((Math.sin(t * 9 + i * 1.7) + 1) * 1.5) + (Math.abs(i) < 3 ? 6 : Math.abs(i) < 6 ? 3 : 0); for (let k = 0; k < h; k++) px(fx + i, fy - k, k < 1 ? C[3] : k < h * 0.45 ? C[2] : k < h - 1 ? C[1] : C[0]); }
