    for (let i = 0; i < n; i++) { const t = i / n * TAU; ctx.fillRect((Math.round(x + Math.cos(t) * r) & ~1) - 1, (Math.round(y + Math.sin(t) * r * 0.62) & ~1) - 1, 4, 4); }
