    if ((e.drumT > 0 || e.buffT > 0) && Math.random() < 0.3) G.parts.push({ x: X + rand(-8, 8), y: y - rand(14, 28), vx: 0, vy: -24, t: 0.35, c: '#ff4030', g: 0, glow: true });
