      if (!rk || !G.obs.includes(rk)) { e.state = 'chase'; return; }
      const ra = Math.atan2(rk.y - e.y, rk.x - e.x), rd = Math.hypot(rk.x - e.x, rk.y - e.y);
      moveTo(ra, e.spd * 1.25);
