        // 바위를 뜯어낸다: 그 엄폐물이 방에서 사라진다
        const R = G.dun.cur; G.obs.splice(G.obs.indexOf(rk), 1); if (R) { R.sprites = (R.sprites || []).filter(s => s.ob !== rk); G.nav = R.nav = buildNav(G.obs); }
