    for (let i = 0; i < 22 * area; i++) { const x = randi(A.x0, A.x1) & ~1, y = randi(A.y0, A.y1) & ~1; if (!inA(x, y) || !decFree(x, y, 8)) continue; dstamp(pick(['straw1', 'straw2']), x - 4, y - 4); }
