      if (blade) return y === 1 || x - 6 > (8 - y) * 0.5 + 5 ? 'n' : y >= 7 ? 'G' : 'g';
      if (y <= 9 && x >= 13 && x <= 18 && y >= 3 && Math.abs(y - (3 + (x - 13) * 0.8)) < 1) return x > 16 ? 'O' : 'o';
