    for (let it = 0; it < 2; it++) { const kill = []; for (let y = 0; y < g.length; y++) for (let x = 0; x < g[0].length; x++) if (g[y][x] === 'k' && [[1, 0], [-1, 0], [0, 1], [0, -1]].some(([a, b]) => ((g[y + b] || [])[x + a] || '.') === '.')) kill.push([x, y]); for (const [x, y] of kill) g[y][x] = '.'; }
